	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.OrgID != orgID {
		return Customer{}, false
	}
	return copyCustomer(c), true
}

// CustomerByID returns a customer of any organization (background jobs and the admin tool).
func (s *Store) CustomerByID(id string) (Customer, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	return copyCustomer(c), ok
}

// Customers returns an organization's customers, oldest first.
func (s *Store) Customers(orgID string) []Customer {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Customer{}
	for _, c := range s.customers {
		if c.OrgID == orgID {
			out = append(out, copyCustomer(c))
		}
	}
	sortCustomers(out)
	return out
}

// SearchCustomers returns an organization's customers whose name or email contains q, ignoring case, oldest first.
func (s *Store) SearchCustomers(orgID, q string) []Customer {
	q = strings.ToLower(strings.TrimSpace(q))
	out := []Customer{}
	for _, c := range s.Customers(orgID) {
		if strings.Contains(strings.ToLower(c.Name), q) || strings.Contains(strings.ToLower(c.Email), q) {
			out = append(out, c)
		}
	}
	return out
}

// FindCustomerByEmail returns the organization's customer with this email address, ignoring case.
func (s *Store) FindCustomerByEmail(orgID, email string) (Customer, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	id, ok := s.customersByEmail[normEmail(email)]
	if !ok {
		return Customer{}, false
	}
	return copyCustomer(s.customers[id]), true
}

// UpdateCustomer changes a customer with f, which may refuse with an error. The ID and organization cannot change.
func (s *Store) UpdateCustomer(orgID, id string, f func(*Customer) error) (Customer, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	old, ok := s.customers[id]
	if !ok || old.OrgID != orgID {
		return Customer{}, ErrNotFound
	}
	c := copyCustomer(old)
	if err := f(&c); err != nil {
		return Customer{}, err
	}
	c.ID, c.OrgID, c.CreatedAt = old.ID, old.OrgID, old.CreatedAt
	c.Name, c.Email = strings.TrimSpace(c.Name), strings.TrimSpace(c.Email)
	if c.Name == "" || !validEmail(c.Email) {
		return Customer{}, invalid("a customer needs a name and a valid email address")
	}
	if c.DefaultPaymentMethod != "" && !strings.HasPrefix(c.DefaultPaymentMethod, "pm_") {
		return Customer{}, invalid("a payment method looks like pm_...")
	}
	if newKey := normEmail(c.Email); newKey != normEmail(old.Email) {
		if other, ok := s.customersByEmail[newKey]; ok && s.customers[other].OrgID == orgID {
			return Customer{}, ErrEmailTaken
		}
		delete(s.customersByEmail, normEmail(old.Email))
		s.customersByEmail[newKey] = c.ID
	}
	s.customers[id] = c
	return copyCustomer(c), nil
}

// DeleteCustomer removes a customer.
func (s *Store) DeleteCustomer(orgID, id string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.OrgID != orgID {
		return ErrNotFound
	}
	delete(s.customers, id)
	if s.customersByEmail[normEmail(c.Email)] == id {
		delete(s.customersByEmail, normEmail(c.Email))
	}
	return nil
}

func copyCustomer(c Customer) Customer {
	if c.Metadata != nil {
		m := make(map[string]string, len(c.Metadata))
		for k, v := range c.Metadata {
			m[k] = v
		}
		c.Metadata = m
	}
	return c
}

func sortCustomers(cs []Customer) {
	sort.Slice(cs, func(i, j int) bool {
		if !cs[i].CreatedAt.Equal(cs[j].CreatedAt) {
			return cs[i].CreatedAt.Before(cs[j].CreatedAt)
		}
		return cs[i].ID < cs[j].ID
	})
}

package api

import (
	"encoding/base64"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"strconv"
	"time"

	"example.com/tally/internal/store"
)

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

// writeError answers {"error": code, "message": message}.
func writeError(w http.ResponseWriter, status int, code, message string) {
	writeJSON(w, status, map[string]string{"error": code, "message": message})
}

// decode reads a JSON body (at most 1 MiB) into v, or answers 400 and returns false.
func decode(w http.ResponseWriter, r *http.Request, v any) bool {
	dec := json.NewDecoder(io.LimitReader(r.Body, 1<<20))
	if err := dec.Decode(v); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "the body is not valid JSON: "+err.Error())
		return false
	}
	return true
}

// storeError answers for an error from the store or a service.
func (s *Server) storeError(w http.ResponseWriter, err error) {
	switch {
	case errors.Is(err, store.ErrNotFound):
		writeError(w, http.StatusNotFound, "not_found", "no such object")
	case errors.Is(err, store.ErrEmailTaken):
		writeError(w, http.StatusConflict, "email_taken", err.Error())
	case errors.Is(err, store.ErrAlreadyMember):
		writeError(w, http.StatusConflict, "already_member", err.Error())
	case errors.Is(err, store.ErrConflict):
		writeError(w, http.StatusConflict, "conflict", err.Error())
	case errors.Is(err, store.ErrCustomerOrgMismatch):
		writeError(w, http.StatusUnprocessableEntity, "customer_org_mismatch", err.Error())
	case errors.Is(err, store.ErrInvalid):
		writeError(w, http.StatusUnprocessableEntity, "invalid", err.Error())
	default:
		s.log.Error("request failed", "err", err)
		writeError(w, http.StatusInternalServerError, "internal", "something went wrong")
	}
}

// list is the shape of every list response. NextCursor is set when there is another page.
type list struct {
	Items      any    `json:"items"`
	NextCursor string `json:"next_cursor,omitempty"`
}

// page is a request for one page of a list: ?limit= (1 to 100, default 20) and ?cursor= (from the previous page).
type page struct {
	limit int
	after *cursor
}

// cursor is where a page starts: after the item with this creation time and ID.
type cursor struct {
	T  time.Time `json:"t"`
	ID string    `json:"id"`
}

func (c cursor) less(o cursor) bool {
	if !c.T.Equal(o.T) {
		return c.T.Before(o.T)
	}
	return c.ID < o.ID
}

// parsePage reads ?limit and ?cursor, or answers 400 and returns false.
func parsePage(w http.ResponseWriter, r *http.Request) (page, bool) {
	p := page{limit: 20}
	if v := r.URL.Query().Get("limit"); v != "" {
		n, err := strconv.Atoi(v)
		if err != nil || n < 1 || n > 100 {
			writeError(w, http.StatusBadRequest, "invalid_limit", "limit is a whole number from 1 to 100")
			return page{}, false
		}
		p.limit = n
	}
	if v := r.URL.Query().Get("cursor"); v != "" {
		b, err := base64.RawURLEncoding.DecodeString(v)
		var c cursor
		if err != nil || json.Unmarshal(b, &c) != nil || c.ID == "" {
			writeError(w, http.StatusBadRequest, "invalid_cursor", "the cursor is not one this API gave out")
			return page{}, false
		}
		p.after = &c
	}
	return p, true
}

func encodeCursor(c cursor) string {
	b, _ := json.Marshal(c)
	return base64.RawURLEncoding.EncodeToString(b)
}

// pageOf returns one page of items, which are sorted by key (creation time, then ID), and the cursor of the next page.
func pageOf[T any](items []T, key func(T) cursor, p page) ([]T, string) {
	start := 0
	if p.after != nil {
		start = len(items)
		for i, it := range items {
			if p.after.less(key(it)) {
				start = i
				break
			}
		}
	}
	end := min(start+p.limit, len(items))
	out := items[start:end]
	next := ""
	if end < len(items) && len(out) > 0 {
		next = encodeCursor(key(out[len(out)-1]))
	}
	return out, next
}
// Package subscriptions runs subscriptions: starting them with their first invoice, changing and canceling them, and
// renewing them when a billing period ends.
package subscriptions

import (
	"context"
	"errors"
	"fmt"
	"time"

	"example.com/tally/internal/billing"
	"example.com/tally/internal/clock"
	"example.com/tally/internal/payments"
	"example.com/tally/internal/store"
)

// Errors.
var (
	ErrPlanInactive = errors.New("the plan is not active")
	ErrCanceled     = errors.New("the subscription is canceled")
)

// Service runs subscriptions.
type Service struct {
	Store     *store.Store
	Payments  *payments.Service
	Clock     clock.Clock
	Publisher payments.Publisher // nil: no events
}

// CreateInput is a new subscription.
type CreateInput struct {
	CustomerID      string
	PlanID          string
	Quantity        int // 0 means 1
	DiscountPercent int
}

// Create starts a subscription now. With a plan that has a trial, the subscription is trialing until the trial ends, and
// its first period starts then. Otherwise its first period starts now; for a licensed plan that period is invoiced at once
// and charged to the customer's default payment method, if it has one (a declined charge makes the subscription past due).
func (s *Service) Create(ctx context.Context, orgID string, in CreateInput) (store.Subscription, error) {
	plan, ok := s.Store.Plan(orgID, in.PlanID)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	if !plan.Active {
		return store.Subscription{}, ErrPlanInactive
	}
	if in.Quantity == 0 {
		in.Quantity = 1
	}
	now := s.Clock.Now()
	sub := store.Subscription{OrgID: orgID, CustomerID: in.CustomerID, PlanID: plan.ID, Quantity: in.Quantity, DiscountPercent: in.DiscountPercent,
		StartedAt: now, CurrentPeriodStart: now}
	if plan.TrialDays > 0 {
		end := now.AddDate(0, 0, plan.TrialDays)
		sub.Status, sub.TrialEnd, sub.CurrentPeriodEnd = store.Trialing, &end, end
	} else {
		sub.Status, sub.CurrentPeriodEnd = store.Active, billing.AddInterval(now, plan.Interval)
	}
	sub, err := s.Store.CreateSubscription(sub, now)
	if err != nil {
		return store.Subscription{}, err
	}
	s.publish(ctx, orgID, "subscription.created", sub)
	if sub.Status == store.Active && plan.UsageType == store.Licensed {
		paid, err := s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
		if err != nil {
			return sub, err
		}
		if !paid {
			if sub, err = s.setStatus(ctx, sub, store.PastDue); err != nil {
				return sub, err
			}
		}
	}
	return sub, nil
}

// UpdateInput changes a subscription; nil fields stay as they are.
type UpdateInput struct {
	PlanID   *string
	Quantity *int
}

// Update changes a subscription's plan or quantity. The change applies at once and is billed from the next period on.
func (s *Service) Update(ctx context.Context, orgID, id string, in UpdateInput) (store.Subscription, error) {
	if in.PlanID != nil {
		p, ok := s.Store.Plan(orgID, *in.PlanID)
		if !ok {
			return store.Subscription{}, store.ErrNotFound
		}
		if !p.Active {
			return store.Subscription{}, ErrPlanInactive
		}
	}
	sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
		if sub.Status == store.Canceled {
			return ErrCanceled
		}
		if in.PlanID != nil {
			sub.PlanID = *in.PlanID
		}
		if in.Quantity != nil {
			sub.Quantity = *in.Quantity
		}
		return nil
	})
	if err != nil {
		return store.Subscription{}, err
	}
	s.publish(ctx, orgID, "subscription.updated", sub)
	return sub, nil
}

// Cancel cancels a subscription now, or at the end of its current period when atPeriodEnd is set. Canceling a canceled
// subscription changes nothing.
func (s *Service) Cancel(ctx context.Context, orgID, id string, atPeriodEnd bool) (store.Subscription, error) {
	now := s.Clock.Now()
	sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
		if sub.Status == store.Canceled {
			return nil
		}
		if atPeriodEnd {
			sub.CancelAtPeriodEnd = true
			return nil
		}
		sub.Status, sub.CanceledAt = store.Canceled, &now
		return nil
	})
	if err != nil {
		return store.Subscription{}, err
	}
	if sub.Status == store.Canceled {
		s.publish(ctx, orgID, "subscription.canceled", sub)
	} else {
		s.publish(ctx, orgID, "subscription.updated", sub)
	}
	return sub, nil
}

// RenewDue renews every subscription, of every organization, whose current period has ended. A subscription set to cancel
// at the end of its period is canceled. Otherwise its next period starts and is invoiced: a licensed plan bills the new
// period in advance, a metered plan bills the usage of the period that ended. A declined charge makes the subscription past
// due. RenewDue returns how many subscriptions it renewed or canceled.
func (s *Service) RenewDue(ctx context.Context) (int, error) {
	now := s.Clock.Now()
	n := 0
	for _, sub := range s.Store.DueSubscriptions(now) {
		if err := ctx.Err(); err != nil {
			return n, err
		}
		if err := s.renew(ctx, sub, now); err != nil {
			return n, fmt.Errorf("renew %s: %w", sub.ID, err)
		}
		n++
	}
	return n, nil
}

func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) error {
	plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
	if !ok {
		return store.ErrNotFound
	}
	if sub.CancelAtPeriodEnd {
		end := sub.CurrentPeriodEnd
		sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
			x.Status, x.CanceledAt = store.Canceled, &end
			return nil
		})
		if err == nil {
			s.publish(ctx, sub.OrgID, "subscription.canceled", sub)
		}
		return err
	}
	start := now
	end := billing.AddInterval(start, plan.Interval)
	paid := true
	var err error
	switch {
	case plan.UsageType == store.Metered && sub.Status != store.Trialing:
		paid, err = s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
	case plan.UsageType == store.Licensed:
		paid, err = s.invoicePeriod(ctx, sub, plan, start, end)
	}
	if err != nil {
		return err
	}
	sub, err = s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
		x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
		if paid {
			x.Status = store.Active
		} else {
			x.Status = store.PastDue
		}
		return nil
	})
	if err != nil {
		return err
	}
	s.publish(ctx, sub.OrgID, "subscription.updated", sub)
	return nil
}

// invoicePeriod invoices one period of a subscription and charges the invoice to the customer's default payment method.
// It reports false when the charge was declined. An invoice that needs no charge is marked paid; one whose customer has no
// payment method stays open and counts as paid here (it is paid by hand).
func (s *Service) invoicePeriod(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (bool, error) {
	var lines []store.Line
	period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
	switch plan.UsageType {
	case store.Licensed:
		if plan.UnitAmount > 0 {
			lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
		}
	case store.Metered:
		if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
			lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
		}
	}
	ps, pe := start, end
	inv, err := s.Store.CreateInvoice(store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: plan.Currency,
		Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}, s.Clock.Now())
	if err != nil {
		return false, err
	}
	s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
	_, _, err = s.Payments.Pay(ctx, sub.OrgID, inv.ID, "")
	var decline *payments.DeclineError
	switch {
	case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
		return true, nil
	case errors.As(err, &decline):
		return false, nil
	default:
		return false, err
	}
}

func (s *Service) setStatus(ctx context.Context, sub store.Subscription, st store.SubStatus) (store.Subscription, error) {
	sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
		x.Status = st
		return nil
	})
	if err == nil {
		s.publish(ctx, sub.OrgID, "subscription.updated", sub)
	}
	return sub, err
}

func (s *Service) publish(ctx context.Context, orgID, typ string, data any) {
	if s.Publisher != nil {
		_ = s.Publisher.Publish(ctx, orgID, typ, data)
	}
}
// Package payments charges invoices through the payment gateway.
package payments

import (
	"context"
	"errors"
	"fmt"

	"example.com/tally/internal/billing"
	"example.com/tally/internal/clock"
	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// ChargeRequest asks the gateway to take money from a payment method.
type ChargeRequest struct {
	Amount        int64 // minor units
	Currency      money.Currency
	PaymentMethod string // "pm_..."
	Description   string
}

// ChargeResult is a successful charge.
type ChargeResult struct {
	Ref string // the gateway's reference, "ch_..."
}

// Gateway is the payment processor.
type Gateway interface {
	Charge(ctx context.Context, req ChargeRequest) (ChargeResult, error)
}

// DeclineError is a charge the card's issuer refused. Nothing was taken.
type DeclineError struct {
	Code string // for example "card_declined", "insufficient_funds"
}

func (e *DeclineError) Error() string { return "card declined: " + e.Code }

// Errors.
var (
	// ErrUnavailable means the gateway could not be reached or failed; nothing was taken and the charge may be retried.
	ErrUnavailable     = errors.New("payment gateway unavailable")
	ErrAlreadyPaid     = errors.New("the invoice is already paid")
	ErrInvoiceVoid     = errors.New("the invoice is void")
	ErrNoPaymentMethod = errors.New("no payment method to charge")
)

// Publisher sends events to the organization's webhook endpoints (webhooks.Service).
type Publisher interface {
	Publish(ctx context.Context, orgID, eventType string, data any) error
}

// Service pays invoices.
type Service struct {
	Store     *store.Store
	Gateway   Gateway
	Clock     clock.Clock
	Publisher Publisher // nil: no events
}

// Pay charges an open invoice's total to paymentMethod, or to the customer's default payment method when it is empty, and
// marks the invoice paid. An invoice whose total is zero or less is marked paid without a charge. A declined charge is
// recorded as a failed payment and returned as a *DeclineError; when the gateway is unavailable nothing is recorded and the
// error wraps ErrUnavailable.
func (s *Service) Pay(ctx context.Context, orgID, invoiceID, paymentMethod string) (store.Invoice, store.Payment, error) {
	inv, ok := s.Store.Invoice(orgID, invoiceID)
	if !ok {
		return store.Invoice{}, store.Payment{}, store.ErrNotFound
	}
	switch inv.Status {
	case store.InvoicePaid:
		return inv, store.Payment{}, ErrAlreadyPaid
	case store.InvoiceVoid:
		return inv, store.Payment{}, ErrInvoiceVoid
	}
	total := billing.Compute(inv).Total
	if total <= 0 {
		inv, err := s.markPaid(ctx, inv, store.Payment{})
		return inv, store.Payment{}, err
	}
	if paymentMethod == "" {
		if c, ok := s.Store.Customer(orgID, inv.CustomerID); ok {
			paymentMethod = c.DefaultPaymentMethod
		}
	}
	if paymentMethod == "" {
		return inv, store.Payment{}, ErrNoPaymentMethod
	}
	res, err := s.Gateway.Charge(ctx, ChargeRequest{Amount: total, Currency: inv.Currency, PaymentMethod: paymentMethod, Description: "Invoice " + inv.ID})
	var decline *DeclineError
	switch {
	case errors.As(err, &decline):
		p, perr := s.Store.CreatePayment(store.Payment{OrgID: orgID, InvoiceID: inv.ID, Amount: total, Currency: inv.Currency, Status: store.PaymentFailed, FailureCode: decline.Code}, s.Clock.Now())
		if perr != nil {
			return inv, store.Payment{}, perr
		}
		s.publish(ctx, orgID, "invoice.payment_failed", map[string]any{"invoice_id": inv.ID, "payment_id": p.ID, "failure_code": decline.Code})
		return inv, p, err
	case err != nil:
		if errors.Is(err, ErrUnavailable) {
			return inv, store.Payment{}, err
		}
		return inv, store.Payment{}, fmt.Errorf("%w: %v", ErrUnavailable, err)
	}
	p, err := s.Store.CreatePayment(store.Payment{OrgID: orgID, InvoiceID: inv.ID, Amount: total, Currency: inv.Currency, Status: store.PaymentSucceeded, GatewayRef: res.Ref}, s.Clock.Now())
	if err != nil {
		return inv, store.Payment{}, err
	}
	inv, err = s.markPaid(ctx, inv, p)
	return inv, p, err
}

func (s *Service) markPaid(ctx context.Context, inv store.Invoice, p store.Payment) (store.Invoice, error) {
	now := s.Clock.Now()
	inv, err := s.Store.UpdateInvoice(inv.OrgID, inv.ID, func(i *store.Invoice) error {
		i.Status = store.InvoicePaid
		i.PaidAt = &now
		return nil
	})
	if err != nil {
		return store.Invoice{}, err
	}
	s.publish(ctx, inv.OrgID, "invoice.paid", map[string]any{"invoice_id": inv.ID, "payment_id": p.ID, "amount": p.Amount, "currency": inv.Currency})
	return inv, nil
}

func (s *Service) publish(ctx context.Context, orgID, typ string, data any) {
	if s.Publisher != nil {
		_ = s.Publisher.Publish(ctx, orgID, typ, data)
	}
}

