	e.MustDo(http.StatusOK, "GET", "/v1/customers/"+jane.ID, e.Acme.Key, nil, &got)
	if got.Email != "jane@example.com" {
		t.Fatalf("get = %+v", got)
	}
	if r := e.Do("GET", "/v1/customers/"+jane.ID, e.Globex.Key, nil); r.Code != http.StatusNotFound {
