		t.Fatalf("DueSubscriptions = %+v", got)
	}
	if _, err := s.UpdateSubscription(a.ID, sub.ID, func(x *Subscription) error { x.Quantity = 0; return nil }); !errors.Is(err, ErrInvalid) {
		t.Fatalf("quantity 0: %v", err)
	}
}

