276	// Invoice returns one of an organization's invoices.
277	func (s *Store) Invoice(orgID, id string) (Invoice, bool) {
278		s.mu.Lock()
279		defer s.mu.Unlock()
280		inv, ok := s.invoices[id]
281		if !ok || inv.OrgID != orgID {
282			return Invoice{}, false
283		}
284		return copyInvoice(inv), true
285	}
