287	// InvoiceByID returns an invoice of any organization (background jobs and the admin tool).
288	func (s *Store) InvoiceByID(id string) (Invoice, bool) {
289		s.mu.Lock()
290		defer s.mu.Unlock()
291		inv, ok := s.invoices[id]
292		return copyInvoice(inv), ok
293	}
