295	// InvoiceFilter narrows ListInvoices.
296	type InvoiceFilter struct {
297		CustomerID     string
298		SubscriptionID string
299		Status         InvoiceStatus
300	}
301	
302	// ListInvoices returns an organization's invoices that match f, oldest first (ties by ID).
303	func (s *Store) ListInvoices(orgID string, f InvoiceFilter) []Invoice {
304		s.mu.Lock()
305		all := make([]Invoice, 0, len(s.invoices))
306		for _, inv := range s.invoices {
307			all = append(all, inv)
308		}
309		s.mu.Unlock()
310		out := []Invoice{}
311		for _, inv := range all {
312			c := cloneInvoice(inv)
313			if c.OrgID != orgID {
314				continue
315			}
316			if (f.CustomerID != "" && c.CustomerID != f.CustomerID) || (f.SubscriptionID != "" && c.SubscriptionID != f.SubscriptionID) || (f.Status != "" && c.Status != f.Status) {
317				continue
318			}
319			out = append(out, c)
320		}
321		sort.Slice(out, func(i, j int) bool {
322			if !out[i].CreatedAt.Equal(out[j].CreatedAt) {
323				return out[i].CreatedAt.Before(out[j].CreatedAt)
324			}
325			return out[i].ID < out[j].ID
326		})
327		return out
328	}
329	
330	// UpdateInvoice changes an invoice with f, which may refuse with an error. Only its status, timestamps and lines change.
331	func (s *Store) UpdateInvoice(orgID, id string, f func(*Invoice) error) (Invoice, error) {
332		s.mu.Lock()
333		defer s.mu.Unlock()
334		old, ok := s.invoices[id]
335		if !ok || old.OrgID != orgID {
336			return Invoice{}, ErrNotFound
337		}
338		inv := copyInvoice(old)
339		if err := f(&inv); err != nil {
340			return Invoice{}, err
341		}
342		inv.ID, inv.OrgID, inv.CustomerID, inv.SubscriptionID, inv.Currency, inv.CreatedAt = old.ID, old.OrgID, old.CustomerID, old.SubscriptionID, old.Currency, old.CreatedAt
343		s.invoices[id] = copyInvoice(inv)
344		return copyInvoice(inv), nil
345	}
346	
347	// copyInvoice is a deep copy, so callers cannot change stored lines.
348	func copyInvoice(inv Invoice) Invoice {
349		inv.Lines = append([]Line(nil), inv.Lines...)
350		for _, p := range []**time.Time{&inv.PeriodStart, &inv.PeriodEnd, &inv.PaidAt, &inv.VoidedAt} {
351			if *p != nil {
352				t := **p
353				*p = &t
354			}
355		}
356		return inv
357	}
358	
359	// cloneInvoice is a deep copy through JSON, which cannot miss a field added later.
360	func cloneInvoice(inv Invoice) Invoice {
361		b, err := json.Marshal(inv)
362		if err != nil {
363			return copyInvoice(inv)
364		}
365		var out Invoice
366		if err := json.Unmarshal(b, &out); err != nil {
367			return copyInvoice(inv)
368		}
369		return out
370	}
371	
