163	func (s *Server) payError(w http.ResponseWriter, err error) {
164		var decline *payments.DeclineError
165		switch {
166		case errors.As(err, &decline):
167			writeJSON(w, http.StatusPaymentRequired, map[string]string{"error": "payment_declined", "decline_code": decline.Code, "message": err.Error()})
168		case errors.Is(err, payments.ErrAlreadyPaid):
169			writeError(w, http.StatusConflict, "already_paid", err.Error())
170		case errors.Is(err, payments.ErrInvoiceVoid):
171			writeError(w, http.StatusConflict, "invoice_void", err.Error())
172		case errors.Is(err, payments.ErrNoPaymentMethod):
173			writeError(w, http.StatusUnprocessableEntity, "no_payment_method", err.Error())
174		case errors.Is(err, payments.ErrUnavailable):
175			writeError(w, http.StatusServiceUnavailable, "gateway_unavailable", "the payment gateway is unavailable; nothing was charged, try again")
176		default:
177			s.storeError(w, err)
178		}
179	}
