347	// copyInvoice is a deep copy, so callers cannot change stored lines.
348	func copyInvoice(inv Invoice) Invoice {
349		inv.Lines = append([]Line(nil), inv.Lines...)
350		for _, p := range []**time.Time{&inv.PeriodStart, &inv.PeriodEnd, &inv.PaidAt, &inv.VoidedAt} {
351			if *p != nil {
352				t := **p
353				*p = &t
354			}
355		}
356		return inv
357	}
358	
359	// cloneInvoice is a deep copy through JSON, which cannot miss a field added later.
360	func cloneInvoice(inv Invoice) Invoice {
361		b, err := json.Marshal(inv)
362		if err != nil {
363			return copyInvoice(inv)
364		}
365		var out Invoice
366		if err := json.Unmarshal(b, &out); err != nil {
367			return copyInvoice(inv)
368		}
369		return out
370	}
