372	// ---- payments
373	
374	// CreatePayment records a payment attempt for one of the organization's invoices.
375	func (s *Store) CreatePayment(p Payment, now time.Time) (Payment, error) {
376		s.mu.Lock()
377		defer s.mu.Unlock()
378		inv, ok := s.invoices[p.InvoiceID]
379		if !ok || inv.OrgID != p.OrgID {
380			return Payment{}, ErrNotFound
381		}
382		if p.Status != PaymentSucceeded && p.Status != PaymentFailed {
383			return Payment{}, invalid("a payment succeeded or failed")
384		}
385		p.ID = s.newID("pay")
386		p.CreatedAt = now.UTC()
387		s.payments[p.ID] = p
388		return p, nil
389	}
390	
391	// Payments returns an organization's payments, oldest first, only those of one invoice when invoiceID is set.
392	func (s *Store) Payments(orgID, invoiceID string) []Payment {
393		s.mu.Lock()
394		defer s.mu.Unlock()
395		out := []Payment{}
396		for _, p := range s.payments {
397			if p.OrgID == orgID && (invoiceID == "" || p.InvoiceID == invoiceID) {
398				out = append(out, p)
399			}
400		}
401		sort.Slice(out, func(i, j int) bool {
402			if !out[i].CreatedAt.Equal(out[j].CreatedAt) {
403				return out[i].CreatedAt.Before(out[j].CreatedAt)
404			}
405			return out[i].ID < out[j].ID
406		})
407		return out
408	}
