67	// SearchCustomers returns an organization's customers whose name or email contains q, ignoring case, oldest first.
68	func (s *Store) SearchCustomers(orgID, q string) []Customer {
69		q = strings.ToLower(strings.TrimSpace(q))
70		out := []Customer{}
71		for _, c := range s.Customers(orgID) {
