79	// FindCustomerByEmail returns the organization's customer with this email address, ignoring case.
80	func (s *Store) FindCustomerByEmail(orgID, email string) (Customer, bool) {
81		s.mu.Lock()
82		defer s.mu.Unlock()
83		id, ok := s.customersByEmail[customerEmailKey(orgID, email)]
84		if !ok {
85			return Customer{}, false
86		}
87		return copyCustomer(s.customers[id]), true
88	}
89	
90	// UpdateCustomer changes a customer with f, which may refuse with an error. The ID and organization cannot change.
91	func (s *Store) UpdateCustomer(orgID, id string, f func(*Customer) error) (Customer, error) {
92		s.mu.Lock()
93		defer s.mu.Unlock()
94		old, ok := s.customers[id]
95		if !ok || old.OrgID != orgID {
96			return Customer{}, ErrNotFound
97		}
98		c := copyCustomer(old)
99		if err := f(&c); err != nil {
100			return Customer{}, err
101		}
102		c.ID, c.OrgID, c.CreatedAt = old.ID, old.OrgID, old.CreatedAt
103		c.Name, c.Email = strings.TrimSpace(c.Name), strings.TrimSpace(c.Email)
104		if c.Name == "" || !validEmail(c.Email) {
105			return Customer{}, invalid("a customer needs a name and a valid email address")
106		}
107		if c.DefaultPaymentMethod != "" && !strings.HasPrefix(c.DefaultPaymentMethod, "pm_") {
108			return Customer{}, invalid("a payment method looks like pm_...")
109		}
110		if newKey, oldKey := customerEmailKey(orgID, c.Email), customerEmailKey(orgID, old.Email); newKey != oldKey {
111			if _, ok := s.customersByEmail[newKey]; ok {
112				return Customer{}, ErrEmailTaken
113			}
114			delete(s.customersByEmail, oldKey)
115			s.customersByEmail[newKey] = c.ID
116		}
117		s.customers[id] = c
118		return copyCustomer(c), nil
119	}
120	
121	// DeleteCustomer removes a customer.
122	func (s *Store) DeleteCustomer(orgID, id string) error {
123		s.mu.Lock()
124		defer s.mu.Unlock()
125		c, ok := s.customers[id]
126		if !ok || c.OrgID != orgID {
127			return ErrNotFound
128		}
129		delete(s.customers, id)
130		if key := customerEmailKey(orgID, c.Email); s.customersByEmail[key] == id {
131			delete(s.customersByEmail, key)
132		}
133		return nil
134	}
135	
136	func copyCustomer(c Customer) Customer {
137		if c.Metadata != nil {
138			m := make(map[string]string, len(c.Metadata))
139			for k, v := range c.Metadata {
140				m[k] = v
141			}
142			c.Metadata = m
143		}
144		return c
145	}
146	
147	func sortCustomers(cs []Customer) {
148		sort.Slice(cs, func(i, j int) bool {
149			if !cs[i].CreatedAt.Equal(cs[j].CreatedAt) {
150				return cs[i].CreatedAt.Before(cs[j].CreatedAt)
151			}
152			return cs[i].ID < cs[j].ID
153		})
154	}
